CREATE OR REPLACE FUNCTION calculate_retry_success_rate(p_job_type VARCHAR)
RETURNS NUMERIC AS $$
DECLARE
  success_count INT;
  total_retry_count INT;
  success_rate NUMERIC;
BEGIN
  SELECT COUNT(*) INTO success_count
  FROM job_executions
  WHERE job_type = p_job_type
    AND retry_count > 0
    AND final_status = 'success';

  SELECT COUNT(*) INTO total_retry_count
  FROM job_executions
  WHERE job_type = p_job_type
    AND retry_count > 0;

  IF total_retry_count = 0 THEN
    RETURN 0.00;
  END IF;

  success_rate := ROUND((success_count::NUMERIC / total_retry_count::NUMERIC) * 100, 2);

  RETURN success_rate;
END;
$$ LANGUAGE plpgsql;

SELECT calculate_retry_success_rate('data_sync') AS result;
